from typing import List


class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        parent = list(range(threshold + 1))

        def find(a):
            while parent[a] != a:
                parent[a] = parent[parent[a]]
                a = parent[a]
            return a

        small = [v for v in nums if v <= threshold]
        limit = max(small, default=0)
        for v in small:
            root = find(v)
            for m in range(2 * v, limit + 1, v):
                other = find(m)
                if other != root:
                    parent[other] = root
        roots = {find(v) for v in small}
        return len(roots) + len(nums) - len(small)

from typing import List


class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        parent = list(range(10**5 + 1))

        def find(a):
            while parent[a] != a:
                parent[a] = parent[parent[a]]
                a = parent[a]
            return a

        small = [v for v in nums if v <= threshold]
        for v in small:
            root = find(v)
            for m in range(2 * v, min(threshold, 10**5) + 1, v):
                other = find(m)
                if other != root:
                    parent[other] = root
        roots = {find(v) for v in small}
        return len(roots) + len(nums) - len(small)
